import { useState } from 'react';
import {
  call,
  Badge,
  Band,
  DataTable,
  Drawer,
  Field,
  Form,
  LookupSelect,
  Num,
  NumberInput,
  RefName,
  Select,
  Tiles,
  TextInput,
} from '../kit';
import type { PageProps, Row } from '../kit';

const TYPE_OPTIONS: [string, string][] = [
  ['WIDGET', '위젯'],
  ['BANNER', '배너'],
  ['MENU', '메뉴'],
];

const TYPE_NAME: Record<string, string> = {
  WIDGET: '위젯',
  BANNER: '배너',
  MENU: '메뉴',
};

const VISIBLE_OPTIONS: [string, string][] = [
  ['true', '표시'],
  ['false', '숨김'],
];

interface FormState {
  componentType: string;
  componentKey: string;
  menuId: number | string;
  visible: string;
  sortOrder: number | string;
}

const EMPTY: FormState = {
  componentType: 'WIDGET',
  componentKey: '',
  menuId: '',
  visible: 'true',
  sortOrder: '',
};

export default function FnSfr02703Page({ role, notify }: PageProps) {
  // 조회 API가 없어 이 화면에서 저장한 결과를 목록으로 보인다.
  const [saved, setSaved] = useState<Row[]>([]);
  const [open, setOpen] = useState(false);
  const [form, setForm] = useState<FormState>(EMPTY);

  const isMenu = form.componentType === 'MENU';

  function change(patch: Partial<FormState>) {
    setForm({ ...form, ...patch });
  }

  function openNew() {
    setForm(EMPTY);
    setOpen(true);
  }

  function openEdit(row: Row) {
    const type = String(row.componentType);
    setForm({
      componentType: type,
      componentKey: type === 'MENU' ? '' : String(row.componentKey ?? ''),
      menuId: type === 'MENU' ? Number(row.componentKey) : '',
      visible: row.visibleYn ? 'true' : 'false',
      sortOrder: row.sortOrder === undefined || row.sortOrder === null ? '' : (row.sortOrder as number),
    });
    setOpen(true);
  }

  async function submit() {
    // 가정: 메뉴 구성의 componentKey에는 메뉴 ID를 문자열로 보낸다.
    const key = isMenu ? String(form.menuId) : form.componentKey.trim();
    if (isMenu && form.menuId === '') {
      throw new Error('추가할 메뉴를 선택하세요.');
    }
    if (!isMenu && key === '') {
      throw new Error('구성 식별값을 입력하세요.');
    }
    if (form.sortOrder !== '') {
      const n = Number(form.sortOrder);
      if (!Number.isInteger(n) || n < 0) {
        throw new Error('배치 순서는 0 이상의 정수로 입력하세요.');
      }
    }
    const body: Row = {
      componentType: form.componentType,
      componentKey: key,
      visibleYn: form.visible === 'true',
    };
    if (form.sortOrder !== '') {
      body.sortOrder = Number(form.sortOrder);
    }
    const res = await call('PUT', '/portal-personalizations', role, body);
    const next: Row = {
      portalPersonalizationId: res.portalPersonalizationId,
      componentType: body.componentType,
      componentKey: key,
      visibleYn: body.visibleYn,
      sortOrder: body.sortOrder ?? null,
    };
    const rest = saved.filter(
      (r) => !(r.componentType === next.componentType && r.componentKey === next.componentKey),
    );
    setSaved([next, ...rest]);
    setOpen(false);
    notify('개인화 설정을 저장했습니다.');
  }

  const shown = saved.filter((r) => r.visibleYn).length;

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>저장 현황</h2>
        <Tiles
          items={[
            ['저장한 설정', <Num value={saved.length} />],
            ['표시', <Num value={shown} />],
            ['숨김', <Num value={saved.length - shown} />],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>내 포털 구성</h2>
        <Band total={saved.length}>
          <button type="button" onClick={openNew}>
            구성 추가·변경
          </button>
        </Band>
        <DataTable
          rows={saved}
          onRowClick={openEdit}
          empty="이 화면에서 저장한 설정이 없습니다."
          columns={[
            { key: 'componentType', label: '구성 유형', render: (r) => TYPE_NAME[String(r.componentType)] ?? String(r.componentType) },
            {
              key: 'componentKey',
              label: '구성 식별값',
              render: (r) =>
                r.componentType === 'MENU' ? (
                  <RefName table="menu" role={role} value={Number(r.componentKey)} />
                ) : (
                  String(r.componentKey)
                ),
            },
            { key: 'visibleYn', label: '표시 여부', render: (r) => <Badge value={r.visibleYn ? '표시' : '숨김'} /> },
            { key: 'sortOrder', label: '배치 순서', render: (r) => (r.sortOrder === null ? '-' : <Num value={r.sortOrder} />) },
          ]}
        />
      </section>
      {open && (
        <Drawer title="포털 개인화 설정" onClose={() => setOpen(false)}>
          <Form onSubmit={submit} submit="저장">
            <Field label="구성 유형" required>
              <Select
                value={form.componentType}
                onChange={(v) => change({ componentType: v, componentKey: '', menuId: '' })}
                options={TYPE_OPTIONS}
              />
            </Field>
            {isMenu ? (
              <Field label="메뉴" required hint="사용 권한이 있는 메뉴만 추가할 수 있습니다.">
                <LookupSelect
                  table="menu"
                  role={role}
                  value={form.menuId}
                  onChange={(v) => change({ menuId: v })}
                />
              </Field>
            ) : (
              <Field label="구성 식별값" required>
                <TextInput value={form.componentKey} onChange={(v) => change({ componentKey: v })} />
              </Field>
            )}
            <Field label="표시 여부" required>
              <Select value={form.visible} onChange={(v) => change({ visible: v })} options={VISIBLE_OPTIONS} />
            </Field>
            <Field label="배치 순서">
              <NumberInput value={form.sortOrder} onChange={(v) => change({ sortOrder: v })} />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
